-- ============================================================================
-- 20260610100000_psa_consultores_full.sql
-- ----------------------------------------------------------------------------
-- Migração FULL do cluster PSA Consultores (b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3) no MAPA.
-- Reaproveita o mapeamento Fiscal/Tax que já existe no Digital Rotina
-- (cluster_id IS NULL): o backfill toca SOMENTE colunas adicionadas pelo MAPA
-- (cluster_id, project_id) — campos nativos da Rotina e vínculos de sprint
-- ficam intactos. Demais seções são INSERTs novos escopados ao cluster.
--
-- Gerado por .discovery_tmp/gen.mjs a partir de:
--   • etapas reais (process_stages.inputs/outputs/systems/responsible)
--   • project_processes (agrupamento processo→projeto)
--   • ROI consolidado (IAplicada) → process_scenarios
--   • catálogo de ferramentas do código (Digital Dev + Tax Gestão) → melhorias
-- DP (PROC-GERAL-001) e P10-OSG são OSG e ficam de fora.
-- ============================================================================

BEGIN;

-- Guarda: contagem Digital Rotina (cluster NULL) antes — não pode mudar (campos nativos).
DO $g$
BEGIN
  CREATE TEMP TABLE _dr_before ON COMMIT DROP AS
  SELECT 'processes'::text AS t, (SELECT count(*) FROM public.processes WHERE cluster_id IS NULL) AS n
  UNION ALL SELECT 'projects', (SELECT count(*) FROM public.projects WHERE cluster_id IS NULL);
END $g$;

-- gargalo_melhorias (N:M) — idempotente (caso 20260609100000 ainda não tenha rodado)
CREATE TABLE IF NOT EXISTS public.gargalo_melhorias (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  gargalo_id uuid NOT NULL REFERENCES public.gargalos(id) ON DELETE CASCADE,
  melhoria_id uuid NOT NULL REFERENCES public.process_improvements(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT gargalo_melhorias_uniq UNIQUE (gargalo_id, melhoria_id)
);
ALTER TABLE public.gargalo_melhorias ENABLE ROW LEVEL SECURITY;
DO $rls$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='gargalo_melhorias' AND policyname='Team members can read gargalo_melhorias') THEN
    CREATE POLICY "Team members can read gargalo_melhorias" ON public.gargalo_melhorias FOR SELECT
      USING (has_role(auth.uid(),'team_member') OR has_role(auth.uid(),'admin'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='gargalo_melhorias' AND policyname='Team members can write gargalo_melhorias') THEN
    CREATE POLICY "Team members can write gargalo_melhorias" ON public.gargalo_melhorias FOR ALL
      USING (has_role(auth.uid(),'team_member') OR has_role(auth.uid(),'admin'))
      WITH CHECK (has_role(auth.uid(),'team_member') OR has_role(auth.uid(),'admin'));
  END IF;
END $rls$;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.gargalo_melhorias TO authenticated;
GRANT ALL ON public.gargalo_melhorias TO service_role;


