-- ─── 8. Melhorias (= ferramentas reais do código) + junções ───

-- ─── 9. Gargalos + vínculos (processos + melhorias N:M) ───

-- ─── 9b. Cascatas: gargalos-EVENTO (1 etapa-origem) + arestas-ponte p/ a BFS ───

-- ============================================================================
-- 10. VALIDAÇÃO
-- ============================================================================
DO $v$
DECLARE
  v_proc int; v_mel int; v_gar int; v_eventos int; v_seeds int; v_dr_proc_now int; v_dr_proc_before int;
BEGIN
  SELECT count(*) INTO v_proc FROM public.processes WHERE cluster_id='b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3';
  SELECT count(*) INTO v_mel  FROM public.process_improvements WHERE cluster_id='b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3';
  SELECT count(*) INTO v_gar  FROM public.gargalos WHERE cluster_id='b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3';
  SELECT count(*) INTO v_eventos FROM public.gargalos g WHERE g.cluster_id='b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'
    AND EXISTS (SELECT 1 FROM public.gargalo_etapas ge WHERE ge.gargalo_id=g.id);
  SELECT count(*) INTO v_seeds FROM public.gargalo_etapas ge
    WHERE ge.gargalo_id IN (SELECT id FROM public.gargalos WHERE cluster_id='b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3');
  SELECT n INTO v_dr_proc_before FROM _dr_before WHERE t='processes';
  SELECT count(*) INTO v_dr_proc_now FROM public.processes WHERE cluster_id IS NULL;
  RAISE NOTICE 'PSA Consultores: % processos, % melhorias, % gargalos (% eventos de cascata, % seeds)', v_proc, v_mel, v_gar, v_eventos, v_seeds;
  IF v_proc < 25 THEN RAISE EXCEPTION 'Esperados >=25 processos PSA Consultores, encontrados %', v_proc; END IF;
  IF v_mel <> 16 THEN RAISE EXCEPTION 'Esperadas 16 melhorias, encontradas %', v_mel; END IF;
  IF v_gar <> 15 THEN RAISE EXCEPTION 'Esperados 15 gargalos, encontrados %', v_gar; END IF;
  IF v_eventos <> 4 THEN RAISE EXCEPTION 'Esperados 4 gargalos-evento com etapa-origem, encontrados %', v_eventos; END IF;
  -- FK órfã etapa_id+scenario nos seeds de cascata
  IF EXISTS (SELECT 1 FROM public.gargalo_etapas ge
             WHERE ge.gargalo_id IN (SELECT id FROM public.gargalos WHERE cluster_id='b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3')
               AND NOT EXISTS (SELECT 1 FROM public.process_stages ps WHERE ps.id=ge.etapa_id AND ps.scenario=ge.scenario))
  THEN RAISE EXCEPTION 'FK órfã em gargalo_etapas (etapa-origem inexistente)'; END IF;
  IF v_dr_proc_now > v_dr_proc_before THEN RAISE EXCEPTION 'Regressão: NULL processos aumentou'; END IF;
END $v$;

COMMIT;
