INSERT INTO public.gargalos (id, nome, descricao, origem, cluster_id, horas_gastas, taxa_ocorrencia, taxa_captura_apos_melhoria, created_at, updated_at) VALUES (mapa_uuid('gar-psac-ev-quebra'), 'Erro na quebra de documentos propaga para as apurações', 'Um erro ou retificação na quebra dos arquivos (SPED/XML) torna inválidas TODAS as apurações que reaproveitam os "arquivos quebrados": análise de insumos do PIS/COFINS e o preenchimento do WP de DIFAL. Dispara re-quebra e re-apuração a jusante.', 'Processo', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3', 30, 0.6, 0.7, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
