INSERT INTO public.gargalos (id, nome, descricao, origem, cluster_id, horas_gastas, taxa_ocorrencia, taxa_captura_apos_melhoria, created_at, updated_at) VALUES (mapa_uuid('gar-psac-ev-ncm'), 'Reclassificação de NCM invalida apurações de PIS/COFINS e DIFAL', 'Uma mudança na tributação de um NCM (reforma, nova legislação ou correção do Mapa NCM) invalida a análise de insumos do PIS/COFINS e a consulta de benefícios do DIFAL, propagando para o preenchimento do WP, a apuração interna e o comparativo.', 'Externo', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3', 30, 0.6, 0.7, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
