INSERT INTO public.gargalos (id, nome, descricao, origem, cluster_id, horas_gastas, taxa_ocorrencia, taxa_captura_apos_melhoria, created_at, updated_at) VALUES (mapa_uuid('gar-psac-ev-rfb'), 'Notificação/Autuação RFB urgente realoca o sênior e bloqueia a equipe', 'A chegada de uma notificação/autuação da Receita com prazo legal (8–12/mês, imprevisível) dispara uma defesa urgente que exige o sênior, interrompe a fila de revisão e bloqueia os juniores — um "incêndio" que reprioriza toda a carteira de projetos tributários.', 'Cliente', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3', 30, 0.6, 0.7, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
